local config = {
  str_homestory_N24diaoyu_90050101_1_dialog_content = "Vice!",
  str_homestory_N24diaoyu_90050101_2_dialog_content = "Hai, PlayerName.",
  str_homestory_N24diaoyu_90050101_3_dialog_content = "Apakah Anda masih suka menangkap serangga atau mengumpulkan kerang untuk ditambahkan ke koleksi spesimen Anda?<sprite=emo_yihuo size=60 />",
  str_homestory_N24diaoyu_90050101_4_dialog_content = "Saya belum melakukan itu untuk sementara waktu sekarang.",
  str_homestory_N24diaoyu_90050101_5_dialog_content = "Tentu, ada banyak tumbuhan dan hewan berbeda di Cloud Gardens, tetapi masih menjadi tua setelah melakukannya setiap hari dari siang hingga malam.",
  str_homestory_N24diaoyu_90050101_6_dialog_content = "Oh, setiap hari dari siang hingga malam? Anda pasti telah menyatu dengan alam, bukan, PlayerName?",
  str_homestory_N24diaoyu_90050101_7_dialog_content = "Apa yang Anda rencanakan selanjutnya?",
  str_homestory_N24diaoyu_90050101_8_dialog_content = "Bagaimana dengan museum yang memamerkan semua tumbuhan dan hewan di Cloud Gardens untuk dilihat semua orang Aurorian yang berkunjung?",
  str_homestory_N24diaoyu_90050101_9_dialog_content = "<sprite=emo_dianzan size=60 />Itu ide yang bagus! Biarkan aku berpikir...",
  str_homestory_N24diaoyu_90050101_10_dialog_content = "Tapi itu akan menghabiskan banyak uang.<sprite=emo_baiyebi size=60 />",
  str_homestory_N24diaoyu_90050101_11_dialog_content = "Tentu saja. Sebuah museum membutuhkan banyak peralatan untuk melindungi koleksinya.",
  str_homestory_N24diaoyu_90050101_12_dialog_content = "Seperti suhu, sistem kontrol kelembaban dan...",
  str_homestory_N24diaoyu_90050101_13_dialog_content = "Tunggu. Apakah itu Barton barusan?",
  str_homestory_N24diaoyu_90050101_14_dialog_content = "Hah? Seseorang melewati kita? Saya tidak memperhatikan.",
  str_homestory_N24diaoyu_90050101_15_dialog_content = "Sudahlah. Saya mungkin hanya melihat sesuatu di sudut mata saya yang tidak ada.",
  str_homestory_N24diaoyu_90050101_16_dialog_content = "<sprite=emo_laba size=60 />PlayerName! PlayerName!",
  str_homestory_N24diaoyu_90050101_17_dialog_content = "Fi?",
  str_homestory_N24diaoyu_90050101_18_dialog_content = "Ayo bantu, PlayerName! Saya membutuhkan Anda untuk membantu saya dengan banyak hal!",
  str_homestory_N24diaoyu_90050101_19_dialog_content = "Apa, kau bahkan tidak akan berpura-pura meminta bantuan \"kecil\" sekarang?",
  str_homestory_N24diaoyu_90050101_20_dialog_content = "Datang langsung padaku dengan semua masalahmu sekarang...<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050101_21_dialog_content = "Um, saya pikir kita sudah melewati berbelit-belit, PlayerName!",
  str_homestory_N24diaoyu_90050101_22_dialog_content = "Kamu benar. Kalau begitu biarkan aku menolakmu di sini, sekarang juga.",
  str_homestory_N24diaoyu_90050101_23_dialog_content = "Hah? Mengapa!<sprite=emo_xinsui size=60 />",
  str_homestory_N24diaoyu_90050101_24_dialog_content = "saya sibuk. Saya perlu membangun museum di Cloud Gardens.",
  str_homestory_N24diaoyu_90050101_25_dialog_content = "Ini adalah sesuatu yang besar untuk Cloud Gardens. Aku tidak punya waktu untuk bermain-main denganmu.",
  str_homestory_N24diaoyu_90050101_26_dialog_content = "Membantuku adalah \"bermain-main\"!?",
  str_homestory_N24diaoyu_90050101_27_dialog_content = "<sprite=emo_shengqi size=60 />Oke PlayerName, Aku tidak akan membantumu lain kali! Kau akan menyesali ini, dasar bodoh!",
  str_homestory_N24diaoyu_90050101_28_dialog_content = "Dia melarikan diri. Apakah tidak apa-apa meninggalkan Fia sendirian seperti ini?",
  str_homestory_N24diaoyu_90050101_29_dialog_content = "Aku tidak bisa memanjakannya dengan melakukan segalanya untuknya.",
  str_homestory_N24diaoyu_90050101_30_dialog_content = "Pada satu titik atau yang lain, dia perlu belajar untuk memecahkan masalah sendiri. Saya akan memberinya dorongan ekstra ketika dia benar-benar membutuhkannya.",
  str_homestory_N24diaoyu_90050101_31_dialog_content = "Beginilah cara dia tumbuh.",
  str_homestory_N24diaoyu_90050101_32_dialog_content = "<sprite=emo_chidai size=60 />Wah... Anda benar-benar menjadi mentor yang hebat, PlayerName.",
  str_homestory_N24diaoyu_90050101_33_dialog_content = "Entah itu, atau itu hanya pembicaraan di pihak Anda.",
  str_homestory_N24diaoyu_90050101_34_dialog_content = "Heheh...",
  str_homestory_N24diaoyu_90050101_35_dialog_content = "Hah? Apakah Fleur baru saja lewat?",
  str_homestory_N24diaoyu_90050101_36_dialog_content = "Barton, Fia, dan sekarang Fleur... Mengapa mereka semua terburu-buru?",
  str_homestory_N24diaoyu_90050101_37_dialog_content = "Saya tidak tahan dengan ini. Saya harus mengejar mereka dan melihat apa yang terjadi.",
  str_homestory_N24diaoyu_90050102_1_dialog_content = "<sprite=emo_hanshui size=60 />Huff, engah!",
  str_homestory_N24diaoyu_90050102_2_dialog_content = "PlayerName, Anda sebaiknya mengambil nafas sebelum Anda pingsan.",
  str_homestory_N24diaoyu_90050102_3_dialog_content = "Keburukan? PlayerName? Kenapa kalian berdua terengah-engah seperti itu?",
  str_homestory_N24diaoyu_90050102_4_dialog_content = "Aku... Aku mencoba mengejar Fleur.",
  str_homestory_N24diaoyu_90050102_5_dialog_content = "Dan aku berusaha menjadi teman yang baik untuknya.",
  str_homestory_N24diaoyu_90050102_6_dialog_content = "Bagaimana... Bagaimana Fleur bisa berlari begitu cepat? Sepertinya dia bukan tipe atletis.",
  str_homestory_N24diaoyu_90050102_7_dialog_content = "Betulkah? Saya sebenarnya cukup sering melihat Fleur jogging di sekitar Cloud Gardens.",
  str_homestory_N24diaoyu_90050102_8_dialog_content = "Apa? Apakah itu dia sebenarnya? <sprite=emo_tanqi size=60 />Bisa saja membodohiku...",
  str_homestory_N24diaoyu_90050102_9_dialog_content = "Jadi, kenapa kau mengejar Fleur, PlayerName?",
  str_homestory_N24diaoyu_90050102_10_dialog_content = "Atau ... apakah Anda hanya melakukannya untuk bersenang-senang?",
  str_homestory_N24diaoyu_90050102_11_dialog_content = "Untuk kesenangan? Tidak mungkin!",
  str_homestory_N24diaoyu_90050102_12_dialog_content = "Yah... Ini tidak seperti ada sesuatu yang penting. Aku hanya ingin tahu kenapa dia terburu-buru.",
  str_homestory_N24diaoyu_90050102_13_dialog_content = "Itulah definisi \"untuk bersenang-senang\", bukan?<sprite=emo_xiaoku size=60 />",
  str_homestory_N24diaoyu_90050102_14_dialog_content = "Selain lelucon, saya pikir saya tahu apa yang sedang dilakukan Fleur.",
  str_homestory_N24diaoyu_90050102_15_dialog_content = "Betulkah? Anda lakukan?",
  str_homestory_N24diaoyu_90050102_16_dialog_content = "Ya. Menilai dari apa yang dia kenakan, dia mungkin pergi memancing.",
  str_homestory_N24diaoyu_90050102_17_dialog_content = "<sprite=emo_sikao size=60 />Penangkapan ikan...?",
  str_homestory_N24diaoyu_90050102_18_dialog_content = "Ya. Kudengar ini adalah acara yang diselenggarakan bersama oleh penerbit dan banyak guild Umbraton, disarankan oleh Rediesel Desert Aurorian.",
  str_homestory_N24diaoyu_90050102_19_dialog_content = "Ini \"<color=#FFB400>Penangkapan Luar Biasa</color>\"Lomba mancing ternyata cukup hits. Para kontestan dipanggil <color=#FFB400>Pemancing</color>.",
  str_homestory_N24diaoyu_90050102_20_dialog_content = "Fleur pasti ikut kontes dan mencoba untuk bersaing dengan Pemancing lainnya.",
  str_homestory_N24diaoyu_90050102_21_dialog_content = "Hadiah utama dari acara semacam ini pasti berupa suvenir atau semacamnya... Aku hanya tidak menyangka Fleur akan tertarik dengan ini.",
  str_homestory_N24diaoyu_90050102_22_dialog_content = "Saya tidak berpikir itu masalahnya. Hadiah tersebut dikatakan sebagai a <color=#FFB400>joran emas murni dilapisi dengan Lumamber</color>.",
  str_homestory_N24diaoyu_90050102_23_dialog_content = "Emas murni, katamu...?",
  str_homestory_N24diaoyu_90050102_24_dialog_content = "Dan ditutupi dengan Lumamber ...",
  str_homestory_N24diaoyu_90050102_25_dialog_content = "<sprite=emo_mojing size=60 />Ahem! Carleen, kamu pasti tahu bahwa orang-orang di Cloud Gardens memanggilku \"Pemancing Gelombang Naga\".",
  str_homestory_N24diaoyu_90050102_26_dialog_content = "Tidak mungkin aku membiarkan mereka mengambil ikan dariku!",
  str_homestory_N24diaoyu_90050102_27_dialog_content = "(Jika saya menang, saya akan memiliki dana untuk membangun museum!<sprite=emo_baiyebi size=60 />)",
  str_homestory_N24diaoyu_90050102_28_dialog_content = "Anda ingin bergabung?",
  str_homestory_N24diaoyu_90050102_29_dialog_content = "Jika ya, Anda harus menghubungi Bethel, yang mewakili serikat yang menyelenggarakan acara ini...",
  str_homestory_N24diaoyu_90050102_30_dialog_content = "<sprite=emo_dianzan size=60 />Mengerti! Terima kasih, Carleen!",
  str_homestory_N24diaoyu_90050102_31_dialog_content = "Aku bahkan belum selesai.",
  str_homestory_N24diaoyu_90050102_32_dialog_content = "Nah... Kenapa kita tidak ikut kontes bersama PlayerName?",
  str_homestory_N24diaoyu_90050102_33_dialog_content = "Hah?<sprite=emo_yihuo size=60 />",
  str_homestory_N24diaoyu_90050103_1_dialog_content = "Bethel!",
  str_homestory_N24diaoyu_90050103_2_dialog_content = "PlayerName, Keburukan. Oh, dan Lady Carleen juga!",
  str_homestory_N24diaoyu_90050103_3_dialog_content = "Lama tidak bertemu. Apakah Anda menyelesaikan novel yang saya rekomendasikan, Vice?",
  str_homestory_N24diaoyu_90050103_4_dialog_content = "Hampir! Saya menikmati bagaimana itu benar-benar menggali emosi protagonis!",
  str_homestory_N24diaoyu_90050103_5_dialog_content = "Dan hubungannya dengan Genie, teman mekaniknya, juga cukup mengharukan!<sprite=emo_caitiao size=60 />",
  str_homestory_N24diaoyu_90050103_6_dialog_content = "<sprite=emo_aixin size=60 />Benar? Benar? Hubungan seperti itu sangat platonis...",
  str_homestory_N24diaoyu_90050103_7_dialog_content = "Ehem!",
  str_homestory_N24diaoyu_90050103_8_dialog_content = "Vice, kami di sini bukan untuk mengobrol tentang novel...",
  str_homestory_N24diaoyu_90050103_9_dialog_content = "Kami sebenarnya di sini karena kami ingin mendaftar untuk kontes memancing!",
  str_homestory_N24diaoyu_90050103_10_dialog_content = "Oh! Aku tidak tahu kalian semua tertarik memancing!",
  str_homestory_N24diaoyu_90050103_11_dialog_content = "Anda bercanda? Saya adalah Dragonwave Angler dari Cloud Gardens yang terkenal!<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050103_12_dialog_content = "Saya sangat tertarik dengan hadiah utama!<sprite=emo_baiyebi size=60 />",
  str_homestory_N24diaoyu_90050103_13_dialog_content = "Yah... aku di sini karena mereka.",
  str_homestory_N24diaoyu_90050103_14_dialog_content = "Saya mengerti. Tapi, maaf, saya belum pernah mendengar apapun tentang Dragonwave Angler.",
  str_homestory_N24diaoyu_90050103_15_dialog_content = "Oh, dunia akan mengetahui namaku begitu aku membawa pulang hadiah utama!<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050103_16_dialog_content = "Benar... Itu akan menjadi sesuatu yang dinanti-nantikan. Namun...",
  str_homestory_N24diaoyu_90050103_17_dialog_content = "Hmm?",
  str_homestory_N24diaoyu_90050103_18_dialog_content = "Masa pendaftaran telah berakhir.",
  str_homestory_N24diaoyu_90050103_19_dialog_content = "<sprite=emo_xinsui size=60 />Apa!?",
  str_homestory_N24diaoyu_90050103_20_dialog_content = "PlayerName terlihat begitu kecewa. Apakah ini merupakan pukulan besar baginya, tidak bisa mengikuti kontes?",
  str_homestory_N24diaoyu_90050103_21_dialog_content = "Mungkin ... Maksudku, dia bahkan mencoba mencari nama untuk castingnya.",
  str_homestory_N24diaoyu_90050103_22_dialog_content = "Nah... Ada caranya.",
  str_homestory_N24diaoyu_90050103_23_dialog_content = "Ada jalan!?<sprite=emo_yihuo size=60 />",
  str_homestory_N24diaoyu_90050103_24_dialog_content = "Maksudku, ini adalah kontes yang hanya akan menyenangkan jika ada banyak kontestan.",
  str_homestory_N24diaoyu_90050103_25_dialog_content = "Dan itu juga tugas saya untuk memastikan Pemancing yang baik memiliki kesempatan untuk bersinar.",
  str_homestory_N24diaoyu_90050103_26_dialog_content = "Tetapi Anda harus membuktikan diri kepada saya terlebih dahulu.",
  str_homestory_N24diaoyu_90050103_27_dialog_content = "Apa yang Anda sarankan?",
  str_homestory_N24diaoyu_90050103_28_dialog_content = "Lima Knifefish per orang.",
  str_homestory_N24diaoyu_90050103_29_dialog_content = "Orang pertama yang kembali dengan berlima juga mendapat hadiah kejutan!",
  str_homestory_N24diaoyu_90050103_30_dialog_content = "Mengerti! Ayo pergi, Wakil, Carleen!",
  str_homestory_N24diaoyu_90050104_1_dialog_content = "Anda yakin sudah cukup?",
  str_homestory_N24diaoyu_90050104_2_dialog_content = "Ya! ({1}/{2})",
  str_homestory_N24diaoyu_90050104_3_dialog_content = "Hanya beberapa lagi yang tersisa. Sebentar!",
  str_homestory_N24diaoyu_90050104_4_dialog_content = "Semoga berhasil!",
  str_homestory_N24diaoyu_90050104_5_dialog_content = "Yah, itu cepat.",
  str_homestory_N24diaoyu_90050104_6_dialog_content = "<sprite=emo_dianzan size=60 />Seperti PlayerName benar-benar tidak bercanda.",
  str_homestory_N24diaoyu_90050104_7_dialog_content = "Heheh! Tentu saja! Saya kembali ke sini segera setelah saya menangkap ikan!",
  str_homestory_N24diaoyu_90050104_8_dialog_content = "Mereka belum kembali?",
  str_homestory_N24diaoyu_90050104_9_dialog_content = "Tidak. Nah, seperti yang dijanjikan, Anda mendapatkan pilihan pertama pancing Anda, PlayerName.",
  str_homestory_N24diaoyu_90050104_10_dialog_content = "Itu hadiah kejutan yang kamu sebutkan?",
  str_homestory_N24diaoyu_90050104_11_dialog_content = "Ya. Kami menyiapkan banyak joran yang berbeda untuk kontestan kami. Hanya Pemancing yang disetujui yang dapat memegang salah satu joran bersertifikat kami.",
  str_homestory_N24diaoyu_90050104_12_dialog_content = "Jadi apa yang akan Anda miliki? Pancing Api, Air, atau Rumput?",
  str_homestory_N24diaoyu_90050104_13_dialog_content = "Um... Apa bedanya?",
  str_homestory_N24diaoyu_90050104_14_dialog_content = "Anda harus mencari tahu sendiri! Mungkin itu akan memberi Anda keterampilan khusus atau tumbuh bersama Anda. Atau mungkin tidak ada perbedaan sama sekali!",
  str_homestory_N24diaoyu_90050104_15_dialog_content = "Lagipula itu hanya pancing. Tapi begitu Anda memilihnya, itu akan menjadi teman terbaik Anda.",
  str_homestory_N24diaoyu_90050104_16_dialog_content = "Lalu aku akan memilih...",
  str_homestory_N24diaoyu_90050104_17_option_content = "Pancing Rumput!",
  str_homestory_N24diaoyu_90050104_18_option_content = "Pancing Api!",
  str_homestory_N24diaoyu_90050104_19_option_content = "Pancing air!",
  str_homestory_N24diaoyu_90050104_20_dialog_content = "Wow! Rasanya enak dipegang!",
  str_homestory_N24diaoyu_90050104_21_dialog_content = "<sprite=emo_tanqi size=60 />Tapi saya tidak berpikir itu memiliki kemampuan khusus ...",
  str_homestory_N24diaoyu_90050104_22_dialog_content = "Aku pulang.",
  str_homestory_N24diaoyu_90050104_23_dialog_content = "Kau kembali, Carleen.",
  str_homestory_N24diaoyu_90050104_24_dialog_content = "Silakan pilih pancing dari dua yang tersisa.",
  str_homestory_N24diaoyu_90050104_25_dialog_content = "Terserah... Apapun akan dilakukan.",
  str_homestory_N24diaoyu_90050104_26_dialog_content = "Sekarang setelah Anda memiliki joran, mengapa Anda tidak mencobanya?",
  str_homestory_N24diaoyu_90050104_27_dialog_content = "Mari kita mulai putaran pertama kontes sambil menunggu Vice kembali.",
  str_homestory_N24diaoyu_90050104X_1_dialog_content = "PlayerName, joran Anda terlihat kuat.",
  str_homestory_N24diaoyu_90050104X_2_dialog_content = "Apakah Anda siap untuk mengadakan kontes dengan saya terlebih dahulu?",
  str_homestory_N24diaoyu_90050104X_3_option_content = "Aku siap.",
  str_homestory_N24diaoyu_90050104X_4_option_content = "Belum.",
  str_homestory_N24diaoyu_90050105_1_dialog_content = "Kamu cukup bagus dalam hal ini, PlayerName.",
  str_homestory_N24diaoyu_90050105_2_dialog_content = "Anda yakin alami dalam memancing, PlayerName.",
  str_homestory_N24diaoyu_90050105_3_dialog_content = "<sprite=emo_guilian size=60 />Hehehe, bukan hanya itu. Saya memiliki banyak latihan di Cloud Gardens!",
  str_homestory_N24diaoyu_90050105_4_dialog_content = "(Itu, dan banyak orang meminta saya untuk mendapatkan semua jenis ikan untuk mereka.)",
  str_homestory_N24diaoyu_90050105_5_dialog_content = "Hah? Kalian sangat cepat. Aku hanya menangkap cukup sekarang.",
  str_homestory_N24diaoyu_90050105_6_dialog_content = "Tidak apa-apa, Wakil. Kami semua menunggumu.",
  str_homestory_N24diaoyu_90050105_7_dialog_content = "Berikut joran Anda. Anda sekarang seorang Pemancing!",
  str_homestory_N24diaoyu_90050105_8_dialog_content = "Kemudian, saya akan menantikan untuk melihat Anda dalam kontes—",
  str_homestory_N24diaoyu_90050105_9_dialog_content = "Untuk juara—",
  str_homestory_N24diaoyu_90050105_10_dialog_content = "Untuk museum—",
  str_homestory_N24diaoyu_90050105_11_dialog_content = "Untuk Kayu—",
  str_homestory_N24diaoyu_90050105_12_dialog_content = "<sprite=emo_caitiao size=60 />Semoga beruntung!",
  str_homestory_N24diaoyu_90050201_1_dialog_content = "Benar. Sekarang saya adalah Pemancing yang disetujui, saya akan memulai perjalanan saya untuk menjadi juara!",
  str_homestory_N24diaoyu_90050201_2_dialog_content = "Hal pertama yang pertama!",
  str_homestory_N24diaoyu_90050201_3_dialog_content = "Um... Hal pertama...",
  str_homestory_N24diaoyu_90050201_4_dialog_content = "<sprite=emo_xiaoku size=60 />Saya... sepertinya saya belum terbiasa dengan aturannya.",
  str_homestory_N24diaoyu_90050201_5_dialog_content = "Itu memalukan. Mengejar Betel dengan pertanyaan setelah pidato seperti itu...",
  str_homestory_N24diaoyu_90050201_6_dialog_content = "Itu tidak seperti juara.",
  str_homestory_N24diaoyu_90050201_7_dialog_content = "Setiap orang harus tahu tentang aturannya, jadi sama saja jika saya bertanya kepada orang lain! Benar!",
  str_homestory_N24diaoyu_90050201_8_dialog_content = "Hmm? Bukankah itu Lilica di sana? Dia dari Umbraton, dan dia sok tahu.",
  str_homestory_N24diaoyu_90050201_9_dialog_content = "Aku harus pergi bertanya padanya.",
  str_homestory_N24diaoyu_90050202_1_dialog_content = "Lilik.",
  str_homestory_N24diaoyu_90050202_2_dialog_content = "<sprite=emo_laba size=60 />Lilica—",
  str_homestory_N24diaoyu_90050202_3_dialog_content = "Eh?!",
  str_homestory_N24diaoyu_90050202_4_dialog_content = "Kamu menakuti saya...",
  str_homestory_N24diaoyu_90050202_5_dialog_content = "Tidak menyangka akan bertemu denganmu disini, PlayerName.",
  str_homestory_N24diaoyu_90050202_6_dialog_content = "Saya baru saja mendapatkan ide luar biasa untuk sebuah adegan!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050202_7_dialog_content = "Maaf mengganggu pikiran Anda, kalau begitu!",
  str_homestory_N24diaoyu_90050202_8_dialog_content = "Tidak apa-apa. Inspirasi saya mulai mengering. Aku hendak istirahat.",
  str_homestory_N24diaoyu_90050202_9_dialog_content = "Jadi apa yang Anda butuhkan?",
  str_homestory_N24diaoyu_90050202_10_dialog_content = "Sebenarnya, kamu cukup tahu segalanya di sini.",
  str_homestory_N24diaoyu_90050202_11_dialog_content = "Oh? Itu pujian yang bagus. Untuk apa kau mengolesiku?",
  str_homestory_N24diaoyu_90050202_12_dialog_content = "Apakah Anda tahu tentang kontes memancing yang disebut Tangkapan Luar Biasa?",
  str_homestory_N24diaoyu_90050202_13_dialog_content = "Tentu. Itu yang semua orang bicarakan baru-baru ini.",
  str_homestory_N24diaoyu_90050202_14_dialog_content = "Benar... Mungkin aku bisa menulis naskah tentang memancing.",
  str_homestory_N24diaoyu_90050202_15_dialog_content = "Protagonis adalah dua bersaudara, dan ayah mereka adalah seorang guru. Kakak laki-lakinya adalah pria yang baik dan jujur serta mewarisi bisnis keluarga setelah dia lulus.",
  str_homestory_N24diaoyu_90050202_16_dialog_content = "Dan adiknya adalah seorang yang romantis dan memuja alam. Dia belajar metode memancing khusus.",
  str_homestory_N24diaoyu_90050202_17_dialog_content = "Namun, dia kecanduan judi dan hanya bisa keluar dengan bantuan saudaranya.",
  str_homestory_N24diaoyu_90050202_18_dialog_content = "T-Tunggu sebentar... Kamu bisa melakukannya nanti.",
  str_homestory_N24diaoyu_90050202_19_dialog_content = "Setelah Anda memberi tahu saya tentang aturan kontes, jika Anda tahu.",
  str_homestory_N24diaoyu_90050202_20_dialog_content = "Tapi sang kakak hilang, dan sang adik menangkap hiu saat memancing.",
  str_homestory_N24diaoyu_90050202_21_dialog_content = "Dia menemukan tubuh saudaranya di dalam perut hiu, dan ini menjadi kasus pembunuhan yang aneh.",
  str_homestory_N24diaoyu_90050202_22_dialog_content = "Oh! Benar. Anda bertanya kepada saya tentang aturan. Tentu, saya dapat membantu Anda.",
  str_homestory_N24diaoyu_90050202_23_dialog_content = "Sungguh?",
  str_homestory_N24diaoyu_90050202_24_dialog_content = "Tapi Anda tahu bagaimana kelanjutannya. Anda perlu melakukan sesuatu untuk saya.",
  str_homestory_N24diaoyu_90050202_25_dialog_content = "Kumpulkan kayu untukku. Saya ingin membangun satu set.",
  str_homestory_N24diaoyu_90050202_26_dialog_content = "Benar. Aku akan segera kembali.",
  str_homestory_N24diaoyu_90050203_1_dialog_content = "Apakah Anda menemukan kayu? Saya benar-benar mencoba membuat plot yang bagus di sini!",
  str_homestory_N24diaoyu_90050203_2_dialog_content = "Menemukannya! ({1}/{2})",
  str_homestory_N24diaoyu_90050203_3_dialog_content = "Kerja yang baik!",
  str_homestory_N24diaoyu_90050203_4_dialog_content = "Sedikit lagi. Kembali berpikir sebentar lagi!",
  str_homestory_N24diaoyu_90050203_5_dialog_content = "Baiklah baiklah. Cepatlah.",
  str_homestory_N24diaoyu_90050203_6_dialog_content = "Kerja yang baik!",
  str_homestory_N24diaoyu_90050203_7_dialog_content = "Itu cepat.",
  str_homestory_N24diaoyu_90050203_8_dialog_content = "Tentu saja. Saya ahli dalam menjalankan tugas sekarang!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050203_9_dialog_content = "Anda juga cukup berguna sebelumnya saat syuting film. Pernah mempertimbangkan untuk melakukan beberapa pekerjaan di lokasi pemotretan?",
  str_homestory_N24diaoyu_90050203_10_dialog_content = "<sprite=emo_hanshui size=60 />Hahaha... Saya akan memikirkannya. Saya hanya berharap ini akan lebih aman di lain waktu.",
  str_homestory_N24diaoyu_90050203_11_dialog_content = "Heheh. Karena Anda ahli dalam hal ini, bisakah Anda juga memberi saya ikan untuk makan malam?",
  str_homestory_N24diaoyu_90050203_12_dialog_content = "Um... Anda meraup cukup banyak dengan film terakhir. Mengapa Anda perlu menangkap ikan untuk makan malam di Cloud Gardens?",
  str_homestory_N24diaoyu_90050203_13_dialog_content = "Itu namanya hemat! Saya menyimpan uang untuk sekuel Into the Haunted House.",
  str_homestory_N24diaoyu_90050203_14_dialog_content = "Baik. Saya hanya akan menganggapnya sebagai latihan untuk kontes. Tunggu saja di sini untukku.",
  str_homestory_N24diaoyu_90050204_1_dialog_content = "Di mana makan malamku?",
  str_homestory_N24diaoyu_90050204_2_dialog_content = "Wow! Ikan itu terlihat sangat bersemangat. ({1}/{2})",
  str_homestory_N24diaoyu_90050204_3_dialog_content = "Sedikit lagi. Itu tidak cukup, bukan?",
  str_homestory_N24diaoyu_90050204_4_dialog_content = "Tidak apa-apa. Aku belum lapar. Anda dapat mencoba menangkap lebih banyak lagi, PlayerName.",
  str_homestory_N24diaoyu_90050204_5_dialog_content = "<sprite=emo_caitiao size=60 />Wah! Itu banyak. Ini akan cukup untuk berhari-hari.",
  str_homestory_N24diaoyu_90050204_6_dialog_content = "Hmm... Anda berencana makan ikan setiap hari selama beberapa hari ke depan?",
  str_homestory_N24diaoyu_90050204_7_dialog_content = "Saya juga dapat meminta Cellulo untuk mendapatkan beberapa buah untuk saya.",
  str_homestory_N24diaoyu_90050204_8_dialog_content = "(Saya lebih baik melakukan apa yang dikatakan Lilica.)",
  str_homestory_N24diaoyu_90050204_9_dialog_content = "(Saya tidak ingin menyakiti perasaannya dengan mengatakan apa yang saya pikirkan.)",
  str_homestory_N24diaoyu_90050204_10_dialog_content = "Jadi... Bagaimana dengan peraturannya?",
  str_homestory_N24diaoyu_90050204_11_dialog_content = "Benar! Hampir lupa.",
  str_homestory_N24diaoyu_90050204_12_dialog_content = "Anda tidak mempermainkan saya, kan?<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050204_13_dialog_content = "Bercanda! Aku hanya bercanda!",
  str_homestory_N24diaoyu_90050204_14_dialog_content = "Sebenarnya, saya sendiri tidak tahu aturannya, tapi saya kenal seseorang yang tahu.",
  str_homestory_N24diaoyu_90050204_15_dialog_content = "Anda juga harus melewatinya untuk menjadi Pemancing sejati.",
  str_homestory_N24diaoyu_90050204_16_dialog_content = "Maksudmu?",
  str_homestory_N24diaoyu_90050204_17_dialog_content = "Fia. Dia adalah instruktur dan spesialis resmi kontes.",
  str_homestory_N24diaoyu_90050204_18_dialog_content = "Apa... Fia? Aku baru saja menolak permintaannya belum lama ini...",
  str_homestory_N24diaoyu_90050204_19_dialog_content = "Hmm? Apakah sesuatu terjadi di antara kalian berdua?",
  str_homestory_N24diaoyu_90050204_20_dialog_content = "Dia seharusnya bukan tipe orang yang menyimpan dendam, kan? Hanya berbicara dengannya.",
  str_homestory_N24diaoyu_90050204_21_dialog_content = "Ya kamu benar!",
  str_homestory_N24diaoyu_90050204_22_dialog_content = "Yah, terima kasih, Lilica! Sampai jumpa!<sprite=emo_woshou size=60 />",
  str_homestory_N24diaoyu_90050205_1_dialog_content = "Hei, Fia—",
  str_homestory_N24diaoyu_90050205_2_dialog_content = "<sprite=emo_emo size=60 />Nah, bukankah ini Tuan Kurator Museum, PlayerName?",
  str_homestory_N24diaoyu_90050205_3_dialog_content = "Saya pikir Anda adalah orang yang sibuk.",
  str_homestory_N24diaoyu_90050205_4_dialog_content = "Hmm... Masih kesal?",
  str_homestory_N24diaoyu_90050205_5_dialog_content = "(Saatnya mengambil inisiatif untuk meminta maaf!)",
  str_homestory_N24diaoyu_90050205_6_dialog_content = "<sprite=emo_tanqi size=60 />Aku sangat menyesal tentang sebelumnya. Itu kesalahan saya, dan saya telah belajar dari kesalahan saya!",
  str_homestory_N24diaoyu_90050205_7_dialog_content = "Huh! Jadi Anda tidak membuat alasan apapun. Bagus.",
  str_homestory_N24diaoyu_90050205_8_dialog_content = "Anda di sini karena kontes, bukan?",
  str_homestory_N24diaoyu_90050205_9_dialog_content = "Betul sekali. Aku tahu kamu tidak akan menyimpan dendam, Fia!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050205_10_dialog_content = "Jangan berterima kasih padaku. Aku belum bilang aku akan membantumu.",
  str_homestory_N24diaoyu_90050205_11_dialog_content = "Jika Anda ingin masuk ke kontes, Anda harus mengalahkan saya terlebih dahulu.",
  str_homestory_N24diaoyu_90050205_12_dialog_content = "Sekarang, PlayerName, tunjukkan apa yang kamu punya!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050205X_1_dialog_content = "Bisakah kita mulai? Saya orang yang sangat sibuk.",
  str_homestory_N24diaoyu_90050205X_2_option_content = "Ya!",
  str_homestory_N24diaoyu_90050205X_3_option_content = "Saya tiba-tiba teringat ada sesuatu yang harus saya lakukan!",
  str_homestory_N24diaoyu_90050206_1_dialog_content = "Um...! Fia, aku tidak berharap kamu menjadi sebaik ini.",
  str_homestory_N24diaoyu_90050206_2_dialog_content = "Hah? Tidak buruk. Tidak buruk. Saya terkesan, sedikit. Anda lulus.",
  str_homestory_N24diaoyu_90050206_3_dialog_content = "Sekarang saya merasa sedikit lebih baik setelah berolahraga.",
  str_homestory_N24diaoyu_90050206_4_dialog_content = "Aku akan memaafkanmu sebelumnya, kalau begitu.",
  str_homestory_N24diaoyu_90050206_5_dialog_content = "Tapi, jangan Anda pikir saya memberikan yang terbaik. Aku melepaskanmu dengan mudah.",
  str_homestory_N24diaoyu_90050206_6_dialog_content = "Anda membiarkan saya pergi dengan mudah? Kamu luar biasa, Fia!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050206_7_dialog_content = "Oh, sekarang kau hanya menjadi penjilat!",
  str_homestory_N24diaoyu_90050206_8_dialog_content = "Anda lebih baik meluangkan waktu jika ingin menjadi juara.",
  str_homestory_N24diaoyu_90050206_9_dialog_content = "Sekarang, maju dan kalahkan tiga <color=#FFB400>Ahli Pemancing</color>!",
  str_homestory_N24diaoyu_90050206_10_dialog_content = "Pintu menuju kejuaraan hanya akan dibuka setelah Anda mengalahkan tiga Master Angler.",
  str_homestory_N24diaoyu_90050206_11_dialog_content = "Saya akan menantikan hasil Anda.",
  str_homestory_N24diaoyu_90050206_12_dialog_content = "Paham!",
  str_homestory_N24diaoyu_90050301_1_dialog_content = "Hoi, PlayerName!",
  str_homestory_N24diaoyu_90050301_2_dialog_content = "Bangsat? Apa yang kamu lakukan di sini?",
  str_homestory_N24diaoyu_90050301_3_dialog_content = "Sama tua, sama tua. Latihan harian tentunya.<sprite=emo_yaling size=60 />",
  str_homestory_N24diaoyu_90050301_4_dialog_content = "Saya telah berlatih tanpa lelah setiap hari untuk mempersiapkan diri menghadapi takhta Rediesel Wrench.",
  str_homestory_N24diaoyu_90050301_5_dialog_content = "Benar... Aku akan pergi darimu kalau begitu...",
  str_homestory_N24diaoyu_90050301_6_dialog_content = "Tunggu dulu.",
  str_homestory_N24diaoyu_90050301_7_dialog_content = "Hai, PlayerName, tahan. Apakah Anda tidak merasa ada sesuatu yang hilang di Cloud Gardens?",
  str_homestory_N24diaoyu_90050301_8_dialog_content = "Hmm? Apa yang hilang?",
  str_homestory_N24diaoyu_90050301_9_dialog_content = "Jika Anda mengusulkan sesuatu, saya yakin itu tidak berguna.<sprite=emo_xiaoku size=60 />",
  str_homestory_N24diaoyu_90050301_10_dialog_content = "<sprite=emo_shengqi size=60 />Hai! PlayerName! Bagaimana Anda bisa mengatakan itu? Bukankah aku teman terbaikmu?",
  str_homestory_N24diaoyu_90050301_11_dialog_content = "Aku sedang sangat serius! Paling tidak yang bisa Anda lakukan adalah mendengarkan!",
  str_homestory_N24diaoyu_90050301_12_dialog_content = "Baik. Lanjutkan.",
  str_homestory_N24diaoyu_90050301_13_dialog_content = "Ahem! Tidakkah menurutmu kita membutuhkan beberapa fasilitas latihan fisik yang besar di sini?",
  str_homestory_N24diaoyu_90050301_14_dialog_content = "Untuk seorang atlet seperti saya, kesepian dan membosankan di Cloud Gardens.",
  str_homestory_N24diaoyu_90050301_15_dialog_content = "Mengapa Anda tidak menemukan sebuah bangunan dan berlari mengelilinginya?",
  str_homestory_N24diaoyu_90050301_16_dialog_content = "Itu aerobik. Yang saya butuhkan adalah pelatihan resistensi intensitas tinggi!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050301_17_dialog_content = "<sprite=emo_yihuo size=60 />Intensitas tinggi... pelatihan ulang apa?",
  str_homestory_N24diaoyu_90050301_18_dialog_content = "Dapatkan saya beberapa bijih, dan saya akan membuat mesin pelatihan untuk Anda!",
  str_homestory_N24diaoyu_90050301_19_dialog_content = "Hah? Tidak mungkin. Aku sibuk!",
  str_homestory_N24diaoyu_90050301_20_dialog_content = "Sibuk melakukan apa? Anda sibuk mencoba melacak Master Angler, bukan?",
  str_homestory_N24diaoyu_90050301_21_dialog_content = "Kok kau tahu?",
  str_homestory_N24diaoyu_90050301_22_dialog_content = "Yang perlu Anda ketahui adalah: Anda membantu saya, dan saya membantu Anda.",
  str_homestory_N24diaoyu_90050301_23_dialog_content = "Baik... Aku akan mempercayaimu.",
  str_homestory_N24diaoyu_90050302_1_dialog_content = "Anda sudah cukup? Saya tidak sabar!",
  str_homestory_N24diaoyu_90050302_2_dialog_content = "Bagus! Mereka semua ada di sini. ({1}/{2})",
  str_homestory_N24diaoyu_90050302_3_dialog_content = "Sedikit lagi. Tunggu sebentar lagi.",
  str_homestory_N24diaoyu_90050302_4_dialog_content = "Ayo! Darahku mendidih sekarang!",
  str_homestory_N24diaoyu_90050302_5_dialog_content = "Yah, harus kukatakan, kau dalam kondisi yang cukup baik, PlayerName.",
  str_homestory_N24diaoyu_90050302_6_dialog_content = "Berhenti main-main denganku. Katakan saja apa yang perlu saya ketahui tentang kontes!",
  str_homestory_N24diaoyu_90050302_7_dialog_content = "Jangan khawatir, aku akan memberitahumu. Fleur adalah Ahli Pemancing.",
  str_homestory_N24diaoyu_90050302_8_dialog_content = "Apa? Fleur adalah Ahli Pemancing? Saya pikir Rediesel Wrench berbasis di gurun...",
  str_homestory_N24diaoyu_90050302_9_dialog_content = "Terus? Jadi mereka tidak pandai memancing cacing pasir dan sejenisnya?",
  str_homestory_N24diaoyu_90050302_10_dialog_content = "Sebaiknya jangan remehkan dia hanya karena dia anggota Rediesel Wrench.",
  str_homestory_N24diaoyu_90050302_11_dialog_content = "Saya belajar itu dari pengalaman.",
  str_homestory_N24diaoyu_90050302_12_dialog_content = "Oke. Aku akan menemui Fleur kalau begitu.",
  str_homestory_N24diaoyu_90050302_13_dialog_content = "Nanti!",
  str_homestory_N24diaoyu_90050303_1_dialog_content = "Fleur!",
  str_homestory_N24diaoyu_90050303_2_dialog_content = "hai, PlayerName.",
  str_homestory_N24diaoyu_90050303_3_dialog_content = "Anda di sini untuk acara mencicipi?",
  str_homestory_N24diaoyu_90050303_4_dialog_content = "<sprite=emo_yihuo size=60 />Acara mencicipi apa?",
  str_homestory_N24diaoyu_90050303_5_dialog_content = "Saya mendengar dari Brock bahwa Anda adalah Ahli Pemancing. Saya di sini untuk menantang Anda!",
  str_homestory_N24diaoyu_90050303_6_dialog_content = "Benar. Saya memang mendaftar untuk acara itu, yang memberikan pancing gratis, demi mengumpulkan bahan makanan, dan saya mendapatkan beberapa ikan ...",
  str_homestory_N24diaoyu_90050303_7_dialog_content = "Tebak begitulah cara saya menjadi Ahli Pemancing.",
  str_homestory_N24diaoyu_90050303_8_dialog_content = "Mengatakannya seolah itu bukan apa-apa, menurutku kau benar-benar pemancing yang baik, Fleur.",
  str_homestory_N24diaoyu_90050303_9_dialog_content = "Baiklah, jangan menunggu! PlayerName Dragonwave Angler menantang Anda!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050303_10_dialog_content = "Sekarang bukan waktunya. Maaf.",
  str_homestory_N24diaoyu_90050303_11_dialog_content = "Tapi, kenapa?",
  str_homestory_N24diaoyu_90050303_12_dialog_content = "Seperti yang saya katakan, saya sedang menyiapkan bahan makanan untuk acara mencicipi.<sprite=emo_rou size=60 />",
  str_homestory_N24diaoyu_90050303_13_dialog_content = "Ini adalah metode memasak baru yang baru saja saya pelajari.",
  str_homestory_N24diaoyu_90050303_14_dialog_content = "Menyajikan seafood segar dengan bumbu minimal untuk menjaga cita rasa asli bahan makanan.",
  str_homestory_N24diaoyu_90050303_15_dialog_content = "Namun, saya hanya tidak memiliki bahan makanan yang cukup. Apa sakit kepala.",
  str_homestory_N24diaoyu_90050303_16_dialog_content = "Biar kubantu!",
  str_homestory_N24diaoyu_90050303_17_dialog_content = "Betulkah? Anda akan melakukan itu untuk saya?",
  str_homestory_N24diaoyu_90050303_18_dialog_content = "Jika Anda bersedia membantu, saya akan memastikan saya menyiapkannya sehingga kita dapat memulai kompetisi kecil kita. Bagaimana dengan itu, PlayerName?",
  str_homestory_N24diaoyu_90050303_19_dialog_content = "Dapatkan saya beberapa globefish. Anda bisa menganggapnya sebagai pemanasan, PlayerName.",
  str_homestory_N24diaoyu_90050303_20_dialog_content = "Serahkan padaku.",
  str_homestory_N24diaoyu_90050304_1_dialog_content = "Apakah Anda mendapatkan cukup globefish?",
  str_homestory_N24diaoyu_90050304_2_dialog_content = "Ya! ({1}/{2})",
  str_homestory_N24diaoyu_90050304_3_dialog_content = "Hanya beberapa lagi. Anda akan segera mendapatkannya!",
  str_homestory_N24diaoyu_90050304_4_dialog_content = "Oke. Terima kasih banyak.",
  str_homestory_N24diaoyu_90050304_5_dialog_content = "Terima kasih, PlayerName.",
  str_homestory_N24diaoyu_90050304_6_dialog_content = "Ikan ini pasti segar dan hidup.",
  str_homestory_N24diaoyu_90050304_7_dialog_content = "Bagaimana Anda akan mempersiapkan ikan?",
  str_homestory_N24diaoyu_90050304_8_dialog_content = "Yah... ikan yang berbeda memerlukan metode yang berbeda.",
  str_homestory_N24diaoyu_90050304_9_dialog_content = "Ada yang perlu dipotong tulangnya, dan kepala serta organ dalam yang tidak layak makan juga harus dibuang terlebih dahulu.",
  str_homestory_N24diaoyu_90050304_10_dialog_content = "Lalu saya bisa mengisi daging yang indah dan memasukkannya dengan Lumina untuk membunuh parasit di sana.",
  str_homestory_N24diaoyu_90050304_11_dialog_content = "Anda dapat menggunakan Lumina untuk itu!?<sprite=emo_cangshu size=60 />",
  str_homestory_N24diaoyu_90050304_12_dialog_content = "Ya. Itu juga sesuatu yang baru saya pelajari.",
  str_homestory_N24diaoyu_90050304_13_dialog_content = "Adapun globefish yang baru saja Anda bawa, saya perlu hati-hati mengeluarkan organ dalam, mata, dan bahkan darah.",
  str_homestory_N24diaoyu_90050304_14_dialog_content = "Sebenarnya kalau dipikir-pikir, pasti ada beberapa orang di acara itu yang membenci ikan mentah.",
  str_homestory_N24diaoyu_90050304_15_dialog_content = "Memakannya mentah juga bisa menyebabkan gangguan pencernaan pada beberapa orang.",
  str_homestory_N24diaoyu_90050304_16_dialog_content = "Saya ingin tahu apakah Anda bisa memberi saya air segar, PlayerName?",
  str_homestory_N24diaoyu_90050304_17_dialog_content = "Ini akan sempurna jika saya bisa menyiapkan sup ikan untuk semua orang.<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050304_18_dialog_content = "Aku paham.",
  str_homestory_N24diaoyu_90050305_1_dialog_content = "Anda memiliki air?",
  str_homestory_N24diaoyu_90050305_2_dialog_content = "Ya, sudah selesai! ({1}/{2})",
  str_homestory_N24diaoyu_90050305_3_dialog_content = "Belum. Beri aku waktu sebentar.",
  str_homestory_N24diaoyu_90050305_4_dialog_content = "Tentu. Terima kasih.",
  str_homestory_N24diaoyu_90050305_5_dialog_content = "Terima kasih banyak. Anda harus menunggu saya sebentar. Setelah makanan siap, apakah Anda ingin mencobanya terlebih dahulu?",
  str_homestory_N24diaoyu_90050305_6_dialog_content = "Betulkah? Saya tidak punya — tunggu, saya di sini untuk menantang Anda!",
  str_homestory_N24diaoyu_90050305_7_dialog_content = "Itu mungkin benar, PlayerName. Silakan pilih satu untuk dilakukan terlebih dahulu, makan atau bersaing?",
  str_homestory_N24diaoyu_90050305_8_option_content = "Makan",
  str_homestory_N24diaoyu_90050305_9_dialog_content = "Besar. Tolong tunggu disini. Makanan harus siap dalam dua jam.",
  str_homestory_N24diaoyu_90050305_10_dialog_content = "Segitu panjangnya? Ayo kita lakukan kompetisi dulu!",
  str_homestory_N24diaoyu_90050305_11_option_content = "Bersaing",
  str_homestory_N24diaoyu_90050305_12_dialog_content = "Saya mengerti. Jika itu yang Anda inginkan, mari kita mulai!",
  str_homestory_N24diaoyu_90050305X1_1_dialog_content = "Haruskah kita mulai sekarang? Atau mau makan dulu?",
  str_homestory_N24diaoyu_90050305X1_2_option_content = "Baiklah!",
  str_homestory_N24diaoyu_90050305X1_3_option_content = "Tunggu sebentar...",
  str_homestory_N24diaoyu_90050306_1_dialog_content = "<sprite=emo_xuanyun size=60 />Fiuh... Hampir kalah.",
  str_homestory_N24diaoyu_90050306_2_dialog_content = "Ha ha ha! PlayerName, kamu cukup bagus!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050306_3_dialog_content = "Saya mengakui kekalahan saya. Anda mengalahkan saya dengan adil dan jujur.",
  str_homestory_N24diaoyu_90050306_4_dialog_content = "Adil dan jujur, benarkah? Sekarang kau membuatku curiga.",
  str_homestory_N24diaoyu_90050306_5_dialog_content = "Tidak mungkin. Ini kompetisi yang terhormat. Saya sangat serius tentang hal itu.",
  str_homestory_N24diaoyu_90050306_6_dialog_content = "Lagi pula, Anda telah mengalahkan Master Angler sekarang.",
  str_homestory_N24diaoyu_90050401_1_dialog_content = "Sekarang setelah saya beristirahat sebentar, saya harus mencari Master Pemancing berikutnya.",
  str_homestory_N24diaoyu_90050401_2_dialog_content = "Hmm... Aku harus melihat-lihat dan mengumpulkan beberapa intel terlebih dahulu.",
  str_homestory_N24diaoyu_90050401_3_dialog_content = "Hoi, PlayerName!",
  str_homestory_N24diaoyu_90050401_4_dialog_content = "Hei, Barton. Apa itu?",
  str_homestory_N24diaoyu_90050401_5_dialog_content = "Saya mendengar bahwa Anda juga seorang Pemancing, bukan?",
  str_homestory_N24diaoyu_90050401_6_dialog_content = "Anda bahkan mengalahkan Fleur, seorang Master Angler. Tidak buruk. Tidak buruk.",
  str_homestory_N24diaoyu_90050401_7_dialog_content = "Terima kasih atas pujianmu.",
  str_homestory_N24diaoyu_90050401_8_dialog_content = "Tidak terdengar arogan, tapi saya tahu satu atau dua hal tentang memancing.",
  str_homestory_N24diaoyu_90050401_9_dialog_content = "Jika demikian, mari kita mengadakan kompetisi persahabatan kecil.",
  str_homestory_N24diaoyu_90050401_10_dialog_content = "Seharusnya sangat membantu saya untuk diajari satu atau dua pelajaran oleh Anda.",
  str_homestory_N24diaoyu_90050401_11_dialog_content = "Oh? Anda mendaftar untuk kontes juga?",
  str_homestory_N24diaoyu_90050401_12_dialog_content = "Betul sekali. Sebagai pendiri Angkatan Laut Illumina, memancing adalah keterampilan yang dibutuhkan.",
  str_homestory_N24diaoyu_90050401_13_dialog_content = "Datang, PlayerName. Mari kita lihat apa yang Anda punya.",
  str_homestory_N24diaoyu_90050401_14_dialog_content = "Aku tidak akan mudah padamu!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050401_15_dialog_content = "<sprite=emo_daomei size=60 />Sialan... Aku tidak menyangka Barton akan sangat ahli dalam hal ini.",
  str_homestory_N24diaoyu_90050401_16_dialog_content = "Sepertinya jalanmu masih panjang, lemah.<sprite=emo_gezitou size=60 />",
  str_homestory_N24diaoyu_90050401_17_dialog_content = "Anda kurang yakin dalam casting dan reeling Anda.",
  str_homestory_N24diaoyu_90050401_18_dialog_content = "Yang lebih penting adalah Anda dipenuhi dengan keraguan.",
  str_homestory_N24diaoyu_90050401_19_dialog_content = "Jika Anda tidak bisa mengalahkan saya, Anda tidak akan bisa mengalahkan Master Pemancing lainnya.",
  str_homestory_N24diaoyu_90050401_20_dialog_content = "Jika ini hanya permainan bagi Anda, lebih baik Anda menyerah saja sekarang!",
  str_homestory_N24diaoyu_90050401_21_dialog_content = "<sprite=emo_tanqi size=60 />Aku... Bagaimana mungkin aku kalah?",
  str_homestory_N24diaoyu_90050401_22_dialog_content = "Aku bahkan mengalahkan Fleur...",
  str_homestory_N24diaoyu_90050401_23_dialog_content = "Tetapi saya tidak dapat menyangkal bahwa Barton benar-benar ahli dalam hal ini.",
  str_homestory_N24diaoyu_90050401_24_dialog_content = "Saya harus menjadi lebih baik! Tapi bagaimana saya meningkatkan?",
  str_homestory_N24diaoyu_90050401_25_dialog_content = "Pria...",
  str_homestory_N24diaoyu_90050401_26_dialog_content = "Hei, bukankah ini Caelestite kecilku?",
  str_homestory_N24diaoyu_90050401_27_dialog_content = "Oh, Azure...",
  str_homestory_N24diaoyu_90050401_28_dialog_content = "Mengapa wajah panjang? Apakah seseorang menggertak Anda?",
  str_homestory_N24diaoyu_90050401_29_dialog_content = "Aku... Aku kalah dalam kompetisi memancing dari Barton.",
  str_homestory_N24diaoyu_90050401_30_dialog_content = "Jadi ... Anda mendaftar untuk kontes juga?",
  str_homestory_N24diaoyu_90050401_31_dialog_content = "Ya. Tapi aku tidak cukup baik untuk menang.",
  str_homestory_N24diaoyu_90050401_32_dialog_content = "Aku begitu puas diri hanya karena aku mengalahkan Fleur.",
  str_homestory_N24diaoyu_90050401_33_dialog_content = "Tapi, sebenarnya, aku jauh dari pro...",
  str_homestory_N24diaoyu_90050401_34_dialog_content = "Baiklah baiklah. Pernahkah Anda mendengar pepatah yang berbunyi, \"suasana hati yang buruk membuat ikan takut\"?",
  str_homestory_N24diaoyu_90050401_35_dialog_content = "Tidak pernah. Anda baru saja mengada-ada, bukan?",
  str_homestory_N24diaoyu_90050401_36_dialog_content = "Ha ha ha! Kau punya aku, Caelestite kecil.<sprite=emo_aixin size=60 />",
  str_homestory_N24diaoyu_90050401_37_dialog_content = "Mengapa Anda tidak membantu saya? Pergi jalan-jalan, atau lakukan sesuatu. Apa pun.",
  str_homestory_N24diaoyu_90050401_38_dialog_content = "Bagaimana kalau mengambilkanku air?",
  str_homestory_N24diaoyu_90050401_39_dialog_content = "Air? Untuk apa Anda membutuhkan air?",
  str_homestory_N24diaoyu_90050401_40_dialog_content = "Jangan tanya. Lakukan saja kebaikan ini untukku.",
  str_homestory_N24diaoyu_90050402_1_dialog_content = "Anda punya air?",
  str_homestory_N24diaoyu_90050402_2_dialog_content = "Bagus. ({1}/{2})",
  str_homestory_N24diaoyu_90050402_3_dialog_content = "Nah, kamu cepat.",
  str_homestory_N24diaoyu_90050402_4_dialog_content = "Belum…",
  str_homestory_N24diaoyu_90050402_5_dialog_content = "Semangat. Berjanjilah padaku bahwa kamu akan pergi mengambil air terlebih dahulu.",
  str_homestory_N24diaoyu_90050402_6_dialog_content = "Sekarang, turunkan airnya. Bagaimana perasaan Anda sekarang?",
  str_homestory_N24diaoyu_90050402_7_dialog_content = "Hmm... Tidak sekesal sebelumnya.",
  str_homestory_N24diaoyu_90050402_8_dialog_content = "Uh huh. Tahukah Anda mengapa Cloud Gardens dipilih sebagai tempat kontes?",
  str_homestory_N24diaoyu_90050402_9_dialog_content = "Yah... Karena aku tidak keberatan diadakan lomba memancing disini?",
  str_homestory_N24diaoyu_90050402_10_dialog_content = "Itu salah satu alasannya, tapi bukan alasannya.",
  str_homestory_N24diaoyu_90050402_11_dialog_content = "Itu karena ikan di sini di Cloud Gardens berbeda dari ikan di tempat lain.",
  str_homestory_N24diaoyu_90050402_12_dialog_content = "Mereka bisa merasakan emosi terdekat. Jika Anda tidak fokus, atau jika Anda tidak bertekad, mereka dapat merasakannya dan menjadi waspada.",
  str_homestory_N24diaoyu_90050402_13_dialog_content = "Itu sebabnya tempat ini dipilih untuk mengadakan kontes.",
  str_homestory_N24diaoyu_90050402_14_dialog_content = "Dan itu juga alasan mengapa Anda kalah dari Barton.",
  str_homestory_N24diaoyu_90050402_15_dialog_content = "Anda kurang keyakinan dan fokus.",
  str_homestory_N24diaoyu_90050402_16_dialog_content = "Kontes ini tidak hanya menguji teknik Anda, tetapi juga tekad dan komitmen Anda.",
  str_homestory_N24diaoyu_90050402_17_dialog_content = "Begitukah?",
  str_homestory_N24diaoyu_90050402_18_dialog_content = "Barton juga baru saja mengatakan hal serupa.",
  str_homestory_N24diaoyu_90050402_19_dialog_content = "Saya ingin menjadi lebih baik!<sprite=emo_yaling size=60 />",
  str_homestory_N24diaoyu_90050402_20_dialog_content = "Anda mengatakannya dengan sangat baik.",
  str_homestory_N24diaoyu_90050402_21_dialog_content = "Ayo... Caelestite kecil.",
  str_homestory_N24diaoyu_90050402_22_dialog_content = "Saya akan mengajari Anda cara memegang tongkat dengan benar.",
  str_homestory_N24diaoyu_90050402_23_dialog_content = "T-Tunggu! Anda terlalu dekat!",
  str_homestory_N24diaoyu_90050402_24_dialog_content = "Kamu harus sabar. Ini adalah pelajaran yang sangat serius.",
  str_homestory_N24diaoyu_90050402_25_dialog_content = "Anda harus banyak belajar untuk menjadi juara!",
  str_homestory_N24diaoyu_90050402_26_dialog_content = "Yah... Harus kukatakan, Azure memang mengajariku sedikit tentang memancing.",
  str_homestory_N24diaoyu_90050402_27_dialog_content = "Saya akan menantang Barton lagi, sekarang juga!",
  str_homestory_N24diaoyu_90050403_1_dialog_content = "Oh, kau kembali, lemah.<sprite=emo_gezitou size=60 />",
  str_homestory_N24diaoyu_90050403_2_dialog_content = "Itu tampilan yang bagus. Anda terlihat seperti Anda memiliki apa yang diperlukan sekarang.",
  str_homestory_N24diaoyu_90050403_3_dialog_content = "Betul sekali. Aku yang lama sudah mati. Aku adalah aku yang baru!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050403_4_dialog_content = "Apakah Anda ingin melakukannya lagi?",
  str_homestory_N24diaoyu_90050403_5_option_content = "Ayo kita lakukan!",
  str_homestory_N24diaoyu_90050403_6_option_content = "Saya belum siap.",
  str_homestory_N24diaoyu_90050404_1_dialog_content = "Aduh! Aku tersesat!",
  str_homestory_N24diaoyu_90050404_2_dialog_content = "Saya tidak berharap Anda akan dapat tumbuh begitu banyak dalam waktu sesingkat itu.",
  str_homestory_N24diaoyu_90050404_3_dialog_content = "<sprite=emo_woshou size=60 />Saya harus mengakui bahwa Anda lebih baik dari saya sekarang.",
  str_homestory_N24diaoyu_90050404_4_dialog_content = "Aturan adalah aturan ... Saya akan memberi Anda uang saya ...",
  str_homestory_N24diaoyu_90050404_5_dialog_content = "Tunggu sebentar! Tidak ada aturan seperti itu! Ini tidak seperti pertarungan binatang buas yang menakjubkan!",
  str_homestory_N24diaoyu_90050404_6_dialog_content = "Oh... Anda benar.",
  str_homestory_N24diaoyu_90050404_7_dialog_content = "Kemudian, saya akan memberi tahu Anda di mana Anda dapat menemukan Ahli Pemancing berikutnya.",
  str_homestory_N24diaoyu_90050405_1_dialog_content = "Ini harus menjadi tempat di mana Barton menyuruhku pergi.",
  str_homestory_N24diaoyu_90050405_2_dialog_content = "Hmm? Kenapa kamu di sini, Caelestite kecil?",
  str_homestory_N24diaoyu_90050405_3_dialog_content = "Apakah Anda sudah mengalahkan Barton?",
  str_homestory_N24diaoyu_90050405_4_dialog_content = "Ya! Berkat Anda, saya telah mengalahkan Barton!",
  str_homestory_N24diaoyu_90050405_5_dialog_content = "Itu berita bagus.",
  str_homestory_N24diaoyu_90050405_6_dialog_content = "Kau sadar kau berutang padaku, kan?",
  str_homestory_N24diaoyu_90050405_7_dialog_content = "Heheh! Aku berjanji tidak akan melupakannya.",
  str_homestory_N24diaoyu_90050405_8_dialog_content = "Omong-omong, yang dibicarakan Barton seharusnya ada di sini... tapi di mana?",
  str_homestory_N24diaoyu_90050405_9_dialog_content = "Anda sedang melihat dia.",
  str_homestory_N24diaoyu_90050405_10_dialog_content = "Hah? Maksudmu…",
  str_homestory_N24diaoyu_90050405_11_dialog_content = "Itulah yang saya maksud.",
  str_homestory_N24diaoyu_90050405_12_dialog_content = "Apa? Saya harap semangat Anda tidak begitu mudah diredam.",
  str_homestory_N24diaoyu_90050405_13_dialog_content = "Tidak... Aku berpikir tentang kemungkinan itu adalah kamu.",
  str_homestory_N24diaoyu_90050405_14_dialog_content = "Tapi tidak. Saya percaya diri dan berkomitmen. Mari berkompetisi!<sprite=emo_woshou size=60 />",
  str_homestory_N24diaoyu_90050405_15_dialog_content = "Aku lega sekali.",
  str_homestory_N24diaoyu_90050405_16_dialog_content = "Biarkan saya melihat seberapa banyak Anda telah meningkat.",
  str_homestory_N24diaoyu_90050405X_1_option_content = "Yah, aku tidak akan menahan apapun, kalau begitu... Ayo pergi!",
  str_homestory_N24diaoyu_90050405X_2_option_content = "Tidak, saya masih harus berlatih lagi.",
  str_homestory_N24diaoyu_90050406_6_dialog_content = "Baiklah, saya pikir Anda berutang budi kepada saya, namun Anda benar-benar tidak ragu.",
  str_homestory_N24diaoyu_90050406_7_dialog_content = "Karena saya tahu Anda tidak ingin saya bersikap lunak pada Anda, terutama dalam sebuah kompetisi.",
  str_homestory_N24diaoyu_90050406_8_dialog_content = "Betul sekali. Mereka adalah dua hal yang berbeda.",
  str_homestory_N24diaoyu_90050406_9_dialog_content = "Tapi saya benar-benar terkesan dengan bagaimana Anda bisa mengalahkan saya. Dilakukan dengan baik.",
  str_homestory_N24diaoyu_90050406_10_dialog_content = "Dan bahwa Anda tidak lagi terganggu atau terpengaruh oleh hal-hal lain.",
  str_homestory_N24diaoyu_90050406_11_dialog_content = "<sprite=emo_caitiao size=60 />Selamat. Anda telah mengalahkan dua Ahli Pemancing. Anda sekarang adalah Pemancing yang hebat.",
  str_homestory_N24diaoyu_90050501_1_dialog_content = "Benar. Saya telah mengalahkan dua Master Pemancing.",
  str_homestory_N24diaoyu_90050501_2_dialog_content = "Meskipun ada beberapa kemunduran, saya masih berkembang dengan baik.",
  str_homestory_N24diaoyu_90050501_3_dialog_content = "Sekarang, yang saya butuhkan hanyalah mengalahkan satu Master Pemancing terakhir untuk menang!",
  str_homestory_N24diaoyu_90050501_4_dialog_content = "Aku harus mengumpulkan informasi tentang Master Angler terakhir.",
  str_homestory_N24diaoyu_90050501_5_dialog_content = "<sprite=emo_tanqi size=60 />*mendesah*",
  str_homestory_N24diaoyu_90050501_6_dialog_content = "Hah? Suara itu?",
  str_homestory_N24diaoyu_90050501_7_dialog_content = "Axelia? Mengapa Anda di sini mendesah seperti itu?",
  str_homestory_N24diaoyu_90050501_8_dialog_content = "PlayerName…",
  str_homestory_N24diaoyu_90050501_9_dialog_content = "Apakah itu pancing pada Anda? Jadi kau juga seorang...",
  str_homestory_N24diaoyu_90050501_10_dialog_content = "Betul sekali. Saya Pemancing Gelombang Naga!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050501_11_dialog_content = "Bagus.",
  str_homestory_N24diaoyu_90050501_12_dialog_content = "Aku cemburu.",
  str_homestory_N24diaoyu_90050501_13_dialog_content = "Cemburu dengan bagaimana Anda sehat dan bisa mengikuti kontes memancing, PlayerName.",
  str_homestory_N24diaoyu_90050501_14_dialog_content = "Aku sangat cemburu.",
  str_homestory_N24diaoyu_90050501_15_dialog_content = "Um ... Mengapa Anda tidak mendaftar saja jika Anda ingin bergabung juga?",
  str_homestory_N24diaoyu_90050501_16_dialog_content = "Saya sudah menjadi Pemancing, sebenarnya.",
  str_homestory_N24diaoyu_90050501_17_dialog_content = "Tapi saya ingin bergabung dengan regu Pemancing.",
  str_homestory_N24diaoyu_90050501_18_dialog_content = "Sedihnya, pemimpin regu menolak saya, mengatakan saya terlalu tertekan.",
  str_homestory_N24diaoyu_90050501_19_dialog_content = "Aku kesal, tapi sepertinya aku tidak bisa berbuat apa-apa.<sprite=emo_tanqi size=60 />",
  str_homestory_N24diaoyu_90050501_20_dialog_content = "Apa!? Alasan macam apa itu?",
  str_homestory_N24diaoyu_90050501_21_dialog_content = "Tidak mungkin aku meninggalkanmu seperti ini sekarang setelah aku mengetahuinya! Datang. Saya akan berbicara dengan pemimpin regu itu!",
  str_homestory_N24diaoyu_90050502_1_dialog_content = "Kita sudah sampai.",
  str_homestory_N24diaoyu_90050502_2_dialog_content = "Sekarang kita lihat siapa yang berani membully Axelia!",
  str_homestory_N24diaoyu_90050502_3_dialog_content = "Siapa yang menyebabkan semua kebisingan dan keributan?",
  str_homestory_N24diaoyu_90050502_4_dialog_content = "Eh? Suara apa yang familiar itu?",
  str_homestory_N24diaoyu_90050502_5_dialog_content = "T-Tunggu... Fia!?<sprite=emo_yihuo size=60 />",
  str_homestory_N24diaoyu_90050502_6_dialog_content = "Oh, PlayerName.",
  str_homestory_N24diaoyu_90050502_7_dialog_content = "Bagaimana kontesnya? Jangan menjadi cengeng hanya karena kalah dari kontestan lain.",
  str_homestory_N24diaoyu_90050502_8_dialog_content = "Tidak mungkin! Saya sudah mengalahkan dua Master Pemancing!",
  str_homestory_N24diaoyu_90050502_9_dialog_content = "Fleur dan Azure sama-sama terkesan dengan kemampuanku!",
  str_homestory_N24diaoyu_90050502_10_dialog_content = "Dan, saya juga mengalahkan Barton!<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050502_11_dialog_content = "(Meskipun Barton membuat saya malu lebih dulu.)",
  str_homestory_N24diaoyu_90050502_12_dialog_content = "Wah, saya benar-benar terkesan. Saya tidak berpikir Anda memilikinya di dalam diri Anda, PlayerName.",
  str_homestory_N24diaoyu_90050502_13_dialog_content = "Saya akan memberi tahu Anda lebih banyak tentang ikan di sini untuk membantu Anda.",
  str_homestory_N24diaoyu_90050502_14_dialog_content = "Saya benar-benar Pemancing yang baik. Saya tidak membutuhkan itu untuk menang... Tunggu, bukan itu tujuan saya di sini.",
  str_homestory_N24diaoyu_90050502_15_dialog_content = "Lalu, mengapa kamu di sini?",
  str_homestory_N24diaoyu_90050502_16_dialog_content = "Fia, apakah kamu datang dengan pasukan atau semacamnya?",
  str_homestory_N24diaoyu_90050502_17_dialog_content = "Saya yakin melakukannya! Pasukan Full House!",
  str_homestory_N24diaoyu_90050502_18_dialog_content = "Mengapa Anda tidak membiarkan Axelia bergabung?",
  str_homestory_N24diaoyu_90050502_19_dialog_content = "...",
  str_homestory_N24diaoyu_90050502_20_dialog_content = "Yah... I-Itu karena...",
  str_homestory_N24diaoyu_90050502_21_dialog_content = "Kepribadiannya benar-benar tidak cocok dengan pasukan kami.",
  str_homestory_N24diaoyu_90050502_22_dialog_content = "Dan lihat dia! Warna bajunya mirip dengan yang saya pakai.",
  str_homestory_N24diaoyu_90050502_23_dialog_content = "Warna pribadi yang unik sangat penting bagi anggota regu ini!",
  str_homestory_N24diaoyu_90050502_24_dialog_content = "Tapi Anda belum memberinya kesempatan untuk menunjukkan kemampuannya, bukan?",
  str_homestory_N24diaoyu_90050502_25_dialog_content = "Apakah menurut Anda benar menilai buku dari sampulnya?<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050502_26_dialog_content = "Kenapa kau tiba-tiba menjadi marah seperti itu!?",
  str_homestory_N24diaoyu_90050502_27_dialog_content = "Maksud saya, ada persyaratan untuk bergabung dengan skuad. Jika dia benar-benar memiliki apa yang diperlukan, maka buktikan!",
  str_homestory_N24diaoyu_90050502_28_dialog_content = "Kumpulkan bijih, kayu, atau ikan! Tunjukkan saja buktinya dulu!",
  str_homestory_N24diaoyu_90050502_29_dialog_content = "Jangan khawatir, Axelia. Anda pergi mengumpulkan bijih dan kayu. Saya akan membantu Anda dengan ikan.",
  str_homestory_N24diaoyu_90050502_30_dialog_content = "Terima kasih, PlayerName.",
  str_homestory_N24diaoyu_90050503_1_dialog_content = "Anda memiliki segalanya?",
  str_homestory_N24diaoyu_90050503_2_dialog_content = "Bawa mereka ke sini! ({1}/{2})",
  str_homestory_N24diaoyu_90050503_3_dialog_content = "Oh? Dapatkan semuanya begitu cepat?",
  str_homestory_N24diaoyu_90050503_4_dialog_content = "Belum.",
  str_homestory_N24diaoyu_90050503_5_dialog_content = "Anda bisa menyerah kapan saja.",
  str_homestory_N24diaoyu_90050503_6_dialog_content = "Baik. Ku akui aku menilaimu terlalu cepat. Anda mungkin memiliki apa yang diperlukan untuk berada di skuad.",
  str_homestory_N24diaoyu_90050503_7_dialog_content = "Itu berita bagus, Axelia.",
  str_homestory_N24diaoyu_90050503_8_dialog_content = "Terima kasih telah membantuku, PlayerName.",
  str_homestory_N24diaoyu_90050503_9_dialog_content = "<sprite=emo_wuzui size=60 />Tunggu. Telah melakukan PlayerName membantu Anda mengumpulkan mereka?",
  str_homestory_N24diaoyu_90050503_10_dialog_content = "Ya. Terus?",
  str_homestory_N24diaoyu_90050503_11_dialog_content = "<sprite=emo_shengqi size=60 />Terus? Ini ujian untuk Axelia!",
  str_homestory_N24diaoyu_90050503_12_dialog_content = "Bagaimana itu bisa dihitung jika Anda membantunya !?",
  str_homestory_N24diaoyu_90050503_13_dialog_content = "Kamu bahkan tidak peduli ketika aku meminta bantuanmu sebelumnya, dan sekarang kamu berdarah!?",
  str_homestory_N24diaoyu_90050503_14_dialog_content = "Kau hanya menyebalkan!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050503_15_dialog_content = "T-Tunggu, Fia! Saya pikir Anda mengatakan Anda akan memaafkan saya sebelumnya!",
  str_homestory_N24diaoyu_90050503_16_dialog_content = "Aku memaafkanmu untuk sementara! Jangan taruh di belakangku!",
  str_homestory_N24diaoyu_90050503_17_dialog_content = "Huh! Sepertinya aku harus menempatkanmu di tempatmu, PlayerName!",
  str_homestory_N24diaoyu_90050503_18_dialog_content = "Ayo lakukan dengan cara kita melakukannya di antara dua Pemancing!",
  str_homestory_N24diaoyu_90050503_19_dialog_content = "Keluarkan pancingmu, dan jangan berpikir aku akan meremehkanmu kali ini!",
  str_homestory_N24diaoyu_90050503_20_dialog_content = "Aku akan membuatmu memohon dan menangis!",
  str_homestory_N24diaoyu_90050503X1_1_dialog_content = "kamu bodoh PlayerName! Kemarilah agar aku bisa mengalahkanmu!",
  str_homestory_N24diaoyu_90050503X1_2_option_content = "Aku tidak akan pernah mengaku kalah!",
  str_homestory_N24diaoyu_90050503X1_3_option_content = "Saya tidak ingin bersaing sekarang.",
  str_homestory_N24diaoyu_90050504_1_dialog_content = "<sprite=emo_hanshui size=60 />Huff...huff... Fia memang baik.",
  str_homestory_N24diaoyu_90050504_2_dialog_content = "Apakah ini yang Anda benar-benar punya?",
  str_homestory_N24diaoyu_90050504_3_dialog_content = "Syukurlah saya berhasil menang, nyaris. Bisakah kamu tenang sekarang?",
  str_homestory_N24diaoyu_90050504_4_dialog_content = "<sprite=emo_xinsui size=60 />Aku... aku tidak percaya.",
  str_homestory_N24diaoyu_90050504_5_dialog_content = "Tapi kehormatan adalah segalanya bagi seorang Pemancing. Saya akan menafsirkan apa yang terjadi sebelumnya sebagai permintaan maaf.",
  str_homestory_N24diaoyu_90050504_6_dialog_content = "Axelia, aku secara resmi menyambutmu sebagai anggota kedua regu.",
  str_homestory_N24diaoyu_90050504_7_dialog_content = "Terima kasih. Aku akan melakukan yang terbaik.",
  str_homestory_N24diaoyu_90050504_8_dialog_content = "(Apa? Hanya dua orang di regu? Mengapa dia ingin bergabung dengan regu semacam ini?)",
  str_homestory_N24diaoyu_90050504_9_dialog_content = "Nah, itu yang saya sebut akhir yang baik. Saya harus dalam perjalanan untuk menemukan Master Angler berikutnya.",
  str_homestory_N24diaoyu_90050504_10_dialog_content = "Hah? Apa Master Pemancing berikutnya?",
  str_homestory_N24diaoyu_90050504_11_dialog_content = "Anda telah mengalahkan Fleur dan Azure. Saya satu-satunya yang tersisa.",
  str_homestory_N24diaoyu_90050504_12_dialog_content = "Apa? Anda seorang Ahli Pemancing? Saya pikir Anda adalah instrukturnya.",
  str_homestory_N24diaoyu_90050504_13_dialog_content = "Siapa bilang seorang instruktur tidak bisa menjadi Master Angler?<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050504_14_dialog_content = "Mengalahkanku tanpa menyadarinya? Anda benar-benar menyebalkan, Anda tahu.",
  str_homestory_N24diaoyu_90050504_15_dialog_content = "Datang! Ayo pergi beberapa putaran lagi!",
  str_homestory_N24diaoyu_90050601_1_dialog_content = "Tanganku sangat sakit. <sprite=emo_xuanyun size=60 />Diseret memancing oleh Fia selama lebih dari sepuluh jam berturut-turut...",
  str_homestory_N24diaoyu_90050601_2_dialog_content = "Tapi saya telah mengalahkan tiga Ahli Pemancing! PlayerName Dragonwave Angler menang lagi!",
  str_homestory_N24diaoyu_90050601_3_dialog_content = "Ha ha ha! Sekarang saya harus bisa mendapatkan hadiah pancing, menjualnya, dan mendapatkan uang untuk membangun museum!",
  str_homestory_N24diaoyu_90050601_4_dialog_content = "Saya telah bersaing dengan orang lain untuk waktu yang lama. Saya hampir melupakan kenikmatan memancing dengan santai sendirian.",
  str_homestory_N24diaoyu_90050601_5_dialog_content = "Biarkan saya melakukan itu saja, hanya untuk bersantai.",
  str_homestory_N24diaoyu_90050601_6_dialog_content = "<sprite=emo_wuzui size=60 />Hmm!? Kekuatan ini!",
  str_homestory_N24diaoyu_90050601_7_dialog_content = "Seekor ikan yang luar biasa baru saja menggigit umpannya!",
  str_homestory_N24diaoyu_90050601_8_dialog_content = "Heh!!",
  str_homestory_N24diaoyu_90050601_9_dialog_content = "<sprite=emo_baimao size=60 />Hmm... Meong.",
  str_homestory_N24diaoyu_90050601_10_dialog_content = "A-apa yang...",
  str_homestory_N24diaoyu_90050601_11_dialog_content = "Filsafat!? Bagaimana!?",
  str_homestory_N24diaoyu_90050601_12_dialog_content = "Atau apakah ini sejenis ikan yang menyerupai Philyshy?",
  str_homestory_N24diaoyu_90050601_13_dialog_content = "O-Aduh! Itu menyakitkan, PlayerName! Ini aku, Philyshy! Meong!<sprite=emo_baimao size=60 />",
  str_homestory_N24diaoyu_90050601_14_dialog_content = "Tapi... Kenapa kau tertangkap olehku seperti ikan?",
  str_homestory_N24diaoyu_90050601_15_dialog_content = "Apakah itu penting sekarang? Cepat, meong! Kirimkan dokumen ini ke Petugas Vivian untuk saya!",
  str_homestory_N24diaoyu_90050602_1_dialog_content = "Petugas Vivian!",
  str_homestory_N24diaoyu_90050602_2_dialog_content = "PlayerName? Kenapa kamu begitu terburu-buru?",
  str_homestory_N24diaoyu_90050602_3_dialog_content = "I-Ini! Philyshy meminta saya untuk mengirimkan ini kepada Anda secepatnya.",
  str_homestory_N24diaoyu_90050602_4_dialog_content = "Hah? Philyshy, katamu?",
  str_homestory_N24diaoyu_90050602_5_dialog_content = "Coba saya lihat... Hmm, ini seharusnya sudah ada di meja saya kemarin.",
  str_homestory_N24diaoyu_90050602_6_dialog_content = "<sprite=emo_shengqi size=60 />Philyshy... Terkadang saya benar-benar bertanya-tanya apa yang telah dia lakukan.",
  str_homestory_N24diaoyu_90050602_7_dialog_content = "Um... Ada sesuatu yang saya tidak tahu harus saya katakan atau tidak.",
  str_homestory_N24diaoyu_90050602_8_dialog_content = "Saya bertemu dengannya ketika saya sedang memancing.",
  str_homestory_N24diaoyu_90050602_9_dialog_content = "Dia bermalas-malasan dan memancing!?",
  str_homestory_N24diaoyu_90050602_10_dialog_content = "Tidak tidak. Bagaimana saya harus mengatakannya? Bukan karena dia sedang memancing.",
  str_homestory_N24diaoyu_90050602_11_dialog_content = "Aku memancingnya keluar dari air...",
  str_homestory_N24diaoyu_90050602_12_dialog_content = "...",
  str_homestory_N24diaoyu_90050602_13_dialog_content = "Tidak penting. PlayerName, tolong kembali ke Philyshy dan katakan padanya untuk datang ke sini?",
  str_homestory_N24diaoyu_90050603_1_dialog_content = "Philyshy, aku kembali.",
  str_homestory_N24diaoyu_90050603_2_dialog_content = "Anda telah mengirimkan dokumen ke Petugas Vivian? Terima kasih! Meong!",
  str_homestory_N24diaoyu_90050603_3_dialog_content = "Tapi saya masih tidak mengerti mengapa Anda berada di air dan berakhir di ujung pancing saya.",
  str_homestory_N24diaoyu_90050603_4_dialog_content = "Yah... Aku mungkin mencoba menangkap ikan, bermalas-malasan... atau melamun.",
  str_homestory_N24diaoyu_90050603_5_dialog_content = "T-Bukan itu yang penting, meong.",
  str_homestory_N24diaoyu_90050603_6_dialog_content = "Saya mendengar bahwa Anda telah mengalahkan tiga Master Angler, PlayerName.",
  str_homestory_N24diaoyu_90050603_7_dialog_content = "Anda sudah mendengarnya?",
  str_homestory_N24diaoyu_90050603_8_dialog_content = "Ayo, saya seorang perwira intelijen, meong.<sprite=emo_emo size=60 />",
  str_homestory_N24diaoyu_90050603_9_dialog_content = "Betul sekali. Saya telah mengalahkan tiga Ahli Pemancing, jadi saya juaranya!",
  str_homestory_N24diaoyu_90050603_10_dialog_content = "<sprite=emo_yihuo size=60 />Hah? Tapi Anda belum mengalahkan sang juara.",
  str_homestory_N24diaoyu_90050603_11_dialog_content = "Apa? Saya pikir saya akan secara otomatis memenangkan acara tersebut setelah mengalahkan tiga Master Angler.",
  str_homestory_N24diaoyu_90050603_12_dialog_content = "Tentu saja tidak, meong!",
  str_homestory_N24diaoyu_90050603_13_dialog_content = "Anda harus mengalahkan juara sebelumnya!",
  str_homestory_N24diaoyu_90050603_14_dialog_content = "Um... Tidak ada yang peduli untuk memberitahuku itu.",
  str_homestory_N24diaoyu_90050603_15_dialog_content = "Ya ampun.",
  str_homestory_N24diaoyu_90050603_16_dialog_content = "Nah, untuk berterima kasih karena telah membantu saya, saya akan memberi tahu Anda di mana Anda dapat menemukan sang juara.",
  str_homestory_N24diaoyu_90050603_17_dialog_content = "Trims!",
  str_homestory_N24diaoyu_90050603_18_dialog_content = "Omong-omong, Petugas Vivian sedang mencarimu.",
  str_homestory_N24diaoyu_90050603_19_dialog_content = "*Hiks* Aku tahu, meong... Aku masih tidak bisa menghindarinya, bukan?",
  str_homestory_N24diaoyu_90050604_1_dialog_content = "Hah...? Beretta? Anda adalah juara saat ini?",
  str_homestory_N24diaoyu_90050604_2_dialog_content = "Apakah Anda berbicara tentang kontes memancing?",
  str_homestory_N24diaoyu_90050604_3_dialog_content = "Saya ingat melakukannya, tentu saja ...",
  str_homestory_N24diaoyu_90050604_4_dialog_content = "Memancing itu menyenangkan, dan saya pikir saya mengalahkan beberapa ratus Pemancing lainnya tanpa saya benar-benar tahu.",
  str_homestory_N24diaoyu_90050604_5_dialog_content = "Dan kemudian saya entah bagaimana menjadi juara, bukan karena saya peduli dengan gelar seperti itu.<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050604_5X1_dialog_content = "Jadi, apakah Anda di sini untuk menantang saya?",
  str_homestory_N24diaoyu_90050604_6_dialog_content = "Um... Mengatakannya seperti bukan apa-apa, yang terbaik selalu seperti itu, kurasa.",
  str_homestory_N24diaoyu_90050604_7_option_content = "Mari kita lihat siapa yang lebih baik di antara kita!",
  str_homestory_N24diaoyu_90050604_8_option_content = "Saya perlu melakukan lebih banyak persiapan.",
  str_homestory_N24diaoyu_90050605_1_dialog_content = "<sprite=emo_daomei size=60 />Hah...! Bagaimana mungkin?",
  str_homestory_N24diaoyu_90050605_2_dialog_content = "Kamu cukup baik, PlayerName. Kurasa aku harus menganggapmu lebih serius.",
  str_homestory_N24diaoyu_90050605_3_dialog_content = "Tidak ada persaingan sama sekali. Ikan itu hanya pergi ke Beretta seperti dia adalah magnet ikan atau semacamnya.",
  str_homestory_N24diaoyu_90050605_4_dialog_content = "Tidak mungkin aku bisa menang.",
  str_homestory_N24diaoyu_90050605_5_dialog_content = "Apakah ini akhir dari kemenanganku...?<sprite=emo_xinsui size=60 />",
  str_homestory_N24diaoyu_90050605_6_dialog_content = "PlayerName, kamu belum menyerah kan?",
  str_homestory_N24diaoyu_90050605_7_dialog_content = "Apa kau lupa janji kita?",
  str_homestory_N24diaoyu_90050605_8_dialog_content = "Vice! Carleen!",
  str_homestory_N24diaoyu_90050605_9_dialog_content = "PlayerName, tetaplah begitu! Saya akan menyiapkan pesta makanan laut untuk Anda jika Anda menang!",
  str_homestory_N24diaoyu_90050605_10_dialog_content = "Hei, terlihat kalah bukanlah penampilan yang bagus untuk Caelestite kecilku. Sedot!",
  str_homestory_N24diaoyu_90050605_11_dialog_content = "Ayo! Anda telah mengalahkan saya, PlayerName. Tidak mungkin kau akan kalah darinya!",
  str_homestory_N24diaoyu_90050605_12_dialog_content = "<sprite=emo_daku size=60 />Fleur... Azure... dan Fia... Kalian semua ada di sini.",
  str_homestory_N24diaoyu_90050605_13_dialog_content = "Kami tidak akan memaafkanmu jika kau menyerah begitu saja, PlayerName!",
  str_homestory_N24diaoyu_90050605_14_dialog_content = "Itu dia! Aku akan membawamu ke gym bersamaku, PlayerName. Saya baru saja membuat beberapa halter!",
  str_homestory_N24diaoyu_90050605_15_dialog_content = "Barton, kamu juga...",
  str_homestory_N24diaoyu_90050605_16_dialog_content = "Terima kasih telah berada di sini untuk saya, semuanya.<sprite=emo_woshou size=60 />",
  str_homestory_N24diaoyu_90050605_17_dialog_content = "Mengapa Anda membuat saya terlihat seperti bos penjahat terakhir ...?",
  str_homestory_N24diaoyu_90050605_18_dialog_content = "Hai! Kau tidak mengabaikanku, kan?<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050605_19_dialog_content = "Terima kasih semuanya... telah menyemangati saya!",
  str_homestory_N24diaoyu_90050605_20_dialog_content = "Sekarang, izinkan saya menunjukkan kepada Anda keterampilan pamungkas Dragonwave Angler yang pertama dan terakhir!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050605X_1_dialog_content = "Apakah Anda ingin menantang saya lagi? Saya tidak terlalu keberatan.",
  str_homestory_N24diaoyu_90050605X_2_option_content = "Untuk rekan kami!",
  str_homestory_N24diaoyu_90050605X_3_option_content = "Semenit lagi!",
  str_homestory_N24diaoyu_90050606_1_dialog_content = "Oh... Jadi begini rasanya kehilangan...",
  str_homestory_N24diaoyu_90050606_2_dialog_content = "Aku menang... Akhirnya aku menang!",
  str_homestory_N24diaoyu_90050606_3_dialog_content = "Selamat, PlayerName!<sprite=emo_caitiao size=60 />",
  str_homestory_N24diaoyu_90050606_4_dialog_content = "Luar biasa, PlayerName!",
  str_homestory_N24diaoyu_90050606_5_dialog_content = "Saya tersentuh.<sprite=emo_daku size=60 />",
  str_homestory_N24diaoyu_90050606_6_dialog_content = "Anda benar-benar memberikan semua yang Anda punya!",
  str_homestory_N24diaoyu_90050606_7_dialog_content = "Bagaimana Anda benar-benar tumbuh, Caelestite kecilku.<sprite=emo_aixin size=60 />",
  str_homestory_N24diaoyu_90050606_8_dialog_content = "Sekarang itulah yang saya suka dengar!",
  str_homestory_N24diaoyu_90050606_9_dialog_content = "<sprite=emo_sikao size=60 />Apa kau masih mengabaikanku!?",
  str_homestory_N24diaoyu_90050606_10_dialog_content = "Terima kasih... Terima kasih semuanya.",
  str_homestory_N24diaoyu_90050606_11_dialog_content = "Dilakukan dengan baik ... Begitu juga PlayerName juara baru sekarang?",
  str_homestory_N24diaoyu_90050606_12_dialog_content = "Saya kebetulan membawa pembawa acara bersama saya. Kita bisa membagikan hadiahnya sekarang, kan?",
  str_homestory_N24diaoyu_90050606_13_dialog_content = "Yah... Tentang itu...",
  str_homestory_N24diaoyu_90050606_14_dialog_content = "Jomu? Kaulah yang menyarankan ini ke penerbit?",
  str_homestory_N24diaoyu_90050606_15_dialog_content = "Saya terkesan. Saya tidak berpikir Anda akan melakukan apa pun secara gratis.",
  str_homestory_N24diaoyu_90050606_16_dialog_content = "Ngomong-ngomong, di mana hadiahku? Pancing yang sangat menakjubkan itu?",
  str_homestory_N24diaoyu_90050606_17_dialog_content = "Ya, saya sedang membahasnya...",
  str_homestory_N24diaoyu_90050606_18_dialog_content = "Anda tahu, harga Lumamber meroket...",
  str_homestory_N24diaoyu_90050606_19_dialog_content = "Jadi saya harus mengganti permata di pancing untuk sisa bijih dari Brock.",
  str_homestory_N24diaoyu_90050606_20_dialog_content = "Tapi apa artinya itu yang penting, bukan? Maksudku, itu adalah simbol penguasaanmu!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050606_21_dialog_content = "Memberi...",
  str_homestory_N24diaoyu_90050606_22_dialog_content = "Beri aku joran Lumamber emas murniku!!!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050901_1_dialog_content = "Berkompetisi dengan Carleen.",
  str_homestory_N24diaoyu_90050902_1_dialog_content = "Fantastis.",
  str_homestory_N24diaoyu_90050903_1_dialog_content = "Dia adalah kapten...",
  str_homestory_N24diaoyu_90050904_1_dialog_content = "Dia terlihat sangat marah.",
  str_homestory_N24diaoyu_90050905_1_dialog_content = "Mari kita dengarkan dulu apa yang dia katakan.",
  str_homestory_N24diaoyu_90050906_1_dialog_content = "Saya tidak punya waktu untuk menjelaskan, meong. Bawa intel ini ke Petugas Vivian untukku dulu!",
  str_homestory_N24diaoyu_90050907_1_dialog_content = "Tolong bantu saya menelepon Philyshy ke sini.",
  str_homestory_N24diaoyu_90050908_1_dialog_content = "Seperti yang diharapkan dari PlayerName! Anda benar-benar luar biasa!",
  str_homestory_N24diaoyu_90050909_1_dialog_content = "Tidak ada yang terampil seperti Anda, PlayerName.",
  str_homestory_N24diaoyu_90050910_1_dialog_content = "Cemerlang!",
  str_homestory_N24diaoyu_90050911_1_dialog_content = "Aku benar tentangmu, Caelestite kecil.",
  str_homestory_N24diaoyu_90050912_1_dialog_content = "Aku tidak mau mengakuinya, tapi PlayerName benar-benar sangat kuat!",
  str_homestory_N24diaoyu_90050913_1_dialog_content = "Wah! Sungguh kompetisi yang memuaskan!",
  str_homestory_N24diaoyu_90050914_1_dialog_content = "Ayo pergi jika kamu sudah selesai. Ayo berolahraga bersama!",
  str_homestory_N24diaoyu_90050915_1_dialog_content = "Carleen!",
  str_homestory_N24diaoyu_90050915_2_dialog_content = "Hah? Apa itu, PlayerName?",
  str_homestory_N24diaoyu_90050915_3_dialog_content = "Kau terus menatapku seperti ingin mengatakan sesuatu.",
  str_homestory_N24diaoyu_90050915_4_dialog_content = "Yeah, sebenarnya, tapi aku merasa agak...",
  str_homestory_N24diaoyu_90050915_5_dialog_content = "Jangan ragu untuk mengatakan apa pun yang ada di pikiran Anda.",
  str_homestory_N24diaoyu_90050915_6_dialog_content = "Oke, jadi aku akan berkata…",
  str_homestory_N24diaoyu_90050915_7_dialog_content = "Ya.",
  str_homestory_N24diaoyu_90050915_8_dialog_content = "Hmm…",
  str_homestory_N24diaoyu_90050915_9_dialog_content = "Apa?",
  str_homestory_N24diaoyu_90050915_10_dialog_content = "Apakah Anda berlatih memancing secara rahasia, Carleen?",
  str_homestory_N24diaoyu_90050915_11_dialog_content = "…Ketahuan, deh.",
  str_homestory_N24diaoyu_90050915_12_dialog_content = "Saya punya banyak saksi.",
  str_homestory_N24diaoyu_90050915_13_dialog_content = "Ya. Sejak putaran terakhir kami, saya telah mengasah keterampilan saya.",
  str_homestory_N24diaoyu_90050915_14_dialog_content = "Setelah mempelajarimu, PlayerName, dan semua Master Angler, saya merasa telah belajar banyak.",
  str_homestory_N24diaoyu_90050915_15_dialog_content = "Saya bahkan akan mengatakan saya sekarang cukup baik untuk berada di level ketika Anda mengalahkan Beretta.",
  str_homestory_N24diaoyu_90050915_16_dialog_content = "Sungguh?",
  str_homestory_N24diaoyu_90050915_17_dialog_content = "Jadi, ingin mencoba saya?",
